// int8 model on TensorFlow Lite Micro (library: Chirale_TensorFLowLite 2.0.0).
// The same model file runs on both boards.
#pragma once
#include <Chirale_TensorFlowLite.h>
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/schema/schema_generated.h"

#include "hn_model_data.h"       // generated by the notebook: g_model, g_model_len
#include "hn_feature_params.h"   // generated by the notebook: feature and quantisation constants
#include "hn_replay_clips.h"     // generated by the notebook: held out test clips and the PC results for them
#include "hn_features.h"

namespace hn {

constexpr size_t kArenaSize = 48 * 1024;          // working memory for the interpreter; real use is printed by INFO
alignas(16) static uint8_t s_arena[kArenaSize];
static tflite::MicroInterpreter* s_interp = nullptr;
static TfLiteTensor* s_in = nullptr;
static TfLiteTensor* s_out = nullptr;
static int8_t s_featQ[HN_N_FRAMES * HN_N_MELS];

struct InferResult {
  uint8_t  cls;                 // index into HN_CLASS_NAMES
  float    conf;                // probability of that class, 0..1
  uint8_t  confByte;            // same, scaled to 0..255 for the LoRa payload
  int8_t   scores[HN_N_CLASSES];// raw int8 outputs
  uint32_t featUs;              // feature extraction time
  uint32_t inferUs;             // interpreter time
};

// Returns nullptr when ready, otherwise a text that says what went wrong.
inline const char* mlBegin() {
  const tflite::Model* model = tflite::GetModel(g_model);
  if (model->version() != TFLITE_SCHEMA_VERSION) return "model schema version does not match the library";

  // Only the operations this model uses (keeps the program small).
  static tflite::MicroMutableOpResolver<8> resolver;
  resolver.AddConv2D();
  resolver.AddDepthwiseConv2D();
  resolver.AddMaxPool2D();
  resolver.AddMean();
  resolver.AddFullyConnected();
  resolver.AddSoftmax();
  resolver.AddReshape();
  resolver.AddAveragePool2D();

  static tflite::MicroInterpreter interp(model, resolver, s_arena, kArenaSize);
  if (interp.AllocateTensors() != kTfLiteOk) return "AllocateTensors failed (arena too small or unsupported operation)";
  s_interp = &interp;
  s_in = interp.input(0);
  s_out = interp.output(0);

  if (s_in->type != kTfLiteInt8 || s_in->bytes != sizeof(s_featQ)) return "model input is not int8 [1,49,40,1]";
  if (s_out->type != kTfLiteInt8 || s_out->bytes != HN_N_CLASSES) return "model output does not match HN_N_CLASSES";
  if (fabsf(s_in->params.scale - HN_IN_SCALE) > 1e-7f || s_in->params.zero_point != HN_IN_ZP)
    return "hn_feature_params.h and hn_model_data.h come from different training runs";
  featuresInit();
  return nullptr;
}

inline size_t mlArenaUsed() { return s_interp ? s_interp->arena_used_bytes() : 0; }

// Runs the model on features that are already in s_featQ.
inline bool runModel(InferResult& r) {
  memcpy(s_in->data.int8, s_featQ, sizeof(s_featQ));
  const uint32_t t0 = micros();
  if (s_interp->Invoke() != kTfLiteOk) return false;
  r.inferUs = micros() - t0;
  int best = 0;
  for (int i = 0; i < HN_N_CLASSES; i++) {
    r.scores[i] = s_out->data.int8[i];
    if (r.scores[i] > r.scores[best]) best = i;
  }
  r.cls = (uint8_t)best;
  r.conf = ((float)r.scores[best] - (float)HN_OUT_ZP) * HN_OUT_SCALE;
  if (r.conf < 0) r.conf = 0;
  if (r.conf > 1) r.conf = 1;
  r.confByte = (uint8_t)(r.conf * 255.0f + 0.5f);
  return true;
}

// 1 s of int16 audio at 16 kHz -> class.
inline bool classify(const int16_t* audio, InferResult& r) {
  const uint32_t t0 = micros();
  computeFeatures(audio, s_featQ);
  r.featUs = micros() - t0;
  return runModel(r);
}

}  // namespace hn
